export function getWaterfallPointColor(point, series) {
    if (point.color) {
        return point.color;
    }
    return series.color;
}
export function getWaterfallPointSubtotal(point, data) {
    const pointIndex = data.indexOf(point);
    if (pointIndex === -1) {
        return null;
    }
    return data.reduce((sum, d, index) => {
        if (index <= pointIndex) {
            const value = d.total ? 0 : Number(d.y);
            return sum + value;
        }
        return sum;
    }, 0);
}
